{
  "name": "Forensic Discount Auditor",
  "description": "A high-precision retail auditing tool for identifying revenue leakage, discount abuse, and loyalty program fraud using data analysis and Gemini AI reasoning."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Transaction {
  billId: string;
  store: string;
  sales: number;
  discount: number;
  paidAmount: number;
  customerName: string;
  customerPhone: string;
  remarks: string;
  employee: string;
  date: string;
  discountPercentage: number;
}

export interface StoreBenchmarking {
  storeName: string;
  avgDiscount: number;
  totalSales: number;
  totalDiscount: number;
  category: 'High' | 'Low' | 'Average';
  suspiciousCount: number;
}

export interface SuspiciousLoyalty {
  phone: string;
  names: string[];
  transactionCount: number;
  stores: string[];
  employees: string[];
  flags: string[];
}

export interface AuditReport {
  overallAvgDiscount: number;
  totalTransactions: number;
  highDiscountBills: Transaction[]; // > 10%
  extremeDiscountBills: Transaction[]; // 75-90%
  compBills: Transaction[]; // 100%
  storeBenchmarking: StoreBenchmarking[];
  suspiciousLoyalty: SuspiciousLoyalty[];
  aiExecutiveSummary: string;
  aiActionList: string[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { AuditReport } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getForensicSummary = async (auditData: Partial<AuditReport>) => {
  const model = 'gemini-3-flash-preview';

  const prompt = `
    As a Senior Forensic Retail Auditor, analyze the following audit findings and provide:
    1. An Executive Summary focusing on revenue leakage and discount integrity.
    2. A structured "Action List" for management.

    AUDIT DATA:
    - Total Transactions: ${auditData.totalTransactions}
    - System-wide Avg Discount: ${auditData.overallAvgDiscount?.toFixed(2)}%
    - High Discount (>10%) Count: ${auditData.highDiscountBills?.length}
    - Extreme (75-90%) Count: ${auditData.extremeDiscountBills?.length}
    - Complimentary (100%) Count: ${auditData.compBills?.length}
    - Suspicious Loyalty Accounts Found: ${auditData.suspiciousLoyalty?.length}
    - Problematic Stores: ${auditData.storeBenchmarking?.filter(s => s.category === 'High').map(s => s.storeName).join(', ')}

    Identify patterns of "Staff Point Loading" if suspicious loyalty accounts are high.
    Highlight stores providing high discounts with poor or empty remarks.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            executiveSummary: { type: Type.STRING },
            actionList: { 
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          },
          required: ["executiveSummary", "actionList"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return result;
  } catch (error) {
    console.error("Forensic Summary Error:", error);
    return {
      executiveSummary: "Error generating forensic summary. Please review raw data below.",
      actionList: ["Audit API currently unavailable. Review flags manually."]
    };
  }
};

import React from 'react';

interface StatsCardProps {
  title: string;
  value: string | number;
  subtitle?: string;
  icon?: React.ReactNode;
  trend?: 'up' | 'down' | 'neutral';
  color?: string;
}

export const StatsCard: React.FC<StatsCardProps> = ({ title, value, subtitle, icon, trend, color = 'blue' }) => {
  const colorMap: Record<string, string> = {
    blue: 'border-blue-500 text-blue-400',
    red: 'border-red-500 text-red-400',
    green: 'border-green-500 text-green-400',
    yellow: 'border-yellow-500 text-yellow-400',
  };

  return (
    <div className={`bg-slate-800/50 border-l-4 p-5 rounded-lg shadow-lg ${colorMap[color] || colorMap.blue}`}>
      <div className="flex justify-between items-start">
        <div>
          <p className="text-slate-400 text-xs font-semibold uppercase tracking-wider">{title}</p>
          <h3 className="text-2xl font-bold mt-1 text-white">{value}</h3>
          {subtitle && <p className="text-slate-500 text-xs mt-1">{subtitle}</p>}
        </div>
        <div className="bg-slate-700/50 p-2 rounded-md">
          {icon}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  Cell, PieChart, Pie, Legend 
} from 'recharts';
import { 
  ShieldAlert, 
  Search, 
  FileUp, 
  LayoutDashboard, 
  TrendingDown, 
  Users, 
  AlertCircle,
  FileText,
  Activity,
  ArrowRightCircle
} from 'lucide-react';
import { Transaction, AuditReport, StoreBenchmarking, SuspiciousLoyalty } from './types';
import { getForensicSummary } from './geminiService';
import { StatsCard } from './components/StatsCard';

const App: React.FC = () => {
  const [data, setData] = useState<Transaction[]>([]);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'bills' | 'loyalty' | 'stores'>('dashboard');
  const [report, setReport] = useState<AuditReport | null>(null);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      const rows = text.split('\n').map(row => row.split(','));

      // Expected headers (simplified): Store,Sales,Discount,PaidAmount,CustomerName,Phone,Remarks,Employee,Date,BillId
      // We'll skip header row and map
      const headers = rows[0].map(h => h.trim().toLowerCase());
      const parsed: Transaction[] = rows.slice(1)
        .filter(row => row.length >= 7 && row[0].trim() !== '')
        .map((row, idx) => {
          const sales = parseFloat(row[headers.indexOf('sales')]) || 0;
          const discount = Math.abs(parseFloat(row[headers.indexOf('discount')]) || 0);
          const paid = parseFloat(row[headers.indexOf('paidamount')]) || 0;

          return {
            billId: row[headers.indexOf('billid')] || `B-${idx}`,
            store: row[headers.indexOf('store')] || 'Unknown',
            sales,
            discount,
            paidAmount: paid,
            customerName: row[headers.indexOf('customername')] || 'Guest',
            customerPhone: row[headers.indexOf('phone')] || '0000000000',
            remarks: row[headers.indexOf('remarks')] || '',
            employee: row[headers.indexOf('employee')] || 'N/A',
            date: row[headers.indexOf('date')] || new Date().toISOString(),
            discountPercentage: sales > 0 ? (discount / sales) * 100 : 0
          };
        });

      runAudit(parsed);
    };
    reader.readAsText(file);
  };

  const runAudit = async (transactions: Transaction[]) => {
    // 1. Averages
    const totalSales = transactions.reduce((sum, t) => sum + t.sales, 0);
    const totalDiscount = transactions.reduce((sum, t) => sum + t.discount, 0);
    const overallAvgDiscount = totalSales > 0 ? (totalDiscount / totalSales) * 100 : 0;

    // 2. Bill Thresholds
    const highDiscountBills = transactions.filter(t => t.discountPercentage > 10);
    const extremeDiscountBills = transactions.filter(t => t.discountPercentage >= 75 && t.discountPercentage <= 90);
    const compBills = transactions.filter(t => t.discountPercentage === 100);

    // 3. Store Benchmarking
    const storeMap = new Map<string, Transaction[]>();
    transactions.forEach(t => {
      const list = storeMap.get(t.store) || [];
      list.push(t);
      storeMap.set(t.store, list);
    });

    const storeBenchmarking: StoreBenchmarking[] = Array.from(storeMap.entries()).map(([storeName, txs]) => {
      const sSales = txs.reduce((sum, t) => sum + t.sales, 0);
      const sDisc = txs.reduce((sum, t) => sum + t.discount, 0);
      const avg = sSales > 0 ? (sDisc / sSales) * 100 : 0;

      let category: 'High' | 'Low' | 'Average' = 'Average';
      if (avg >= overallAvgDiscount * 1.5) category = 'High';
      else if (avg <= overallAvgDiscount * 0.5) category = 'Low';

      return {
        storeName,
        avgDiscount: avg,
        totalSales: sSales,
        totalDiscount: sDisc,
        category,
        suspiciousCount: txs.filter(t => t.discountPercentage > 10).length
      };
    });

    // 4. Loyalty Fraud
    const phoneMap = new Map<string, { names: Set<string>; txs: Transaction[] }>();
    transactions.forEach(t => {
      if (t.customerPhone === '6666666666') return; // Exclude guest
      const entry = phoneMap.get(t.customerPhone) || { names: new Set(), txs: [] };
      entry.names.add(t.customerName);
      entry.txs.push(t);
      phoneMap.set(t.customerPhone, entry);
    });

    const suspiciousLoyalty: SuspiciousLoyalty[] = Array.from(phoneMap.entries())
      .map(([phone, entry]) => {
        const flags: string[] = [];
        if (entry.names.size > 3) flags.push("Proxy Number (Multi-Name)");
        if (entry.txs.length > 10) flags.push("High Frequency");

        return {
          phone,
          names: Array.from(entry.names),
          transactionCount: entry.txs.length,
          stores: Array.from(new Set(entry.txs.map(t => t.store))),
          employees: Array.from(new Set(entry.txs.map(t => t.employee))),
          flags
        };
      })
      .filter(s => s.flags.length > 0);

    const baseReport: AuditReport = {
      overallAvgDiscount,
      totalTransactions: transactions.length,
      highDiscountBills,
      extremeDiscountBills,
      compBills,
      storeBenchmarking,
      suspiciousLoyalty,
      aiExecutiveSummary: "Generating forensic report...",
      aiActionList: []
    };

    setReport(baseReport);
    setData(transactions);

    // Call AI for final reasoning
    const aiResponse = await getForensicSummary(baseReport);
    setReport(prev => prev ? { 
      ...prev, 
      aiExecutiveSummary: aiResponse.executiveSummary, 
      aiActionList: aiResponse.actionList 
    } : null);

    setLoading(false);
  };

  const chartData = useMemo(() => {
    if (!report) return [];
    return report.storeBenchmarking
      .sort((a, b) => b.avgDiscount - a.avgDiscount)
      .slice(0, 10);
  }, [report]);

  const discountDistData = [
    { name: '>10%', value: report?.highDiscountBills.length || 0, color: '#f59e0b' },
    { name: '75-90%', value: report?.extremeDiscountBills.length || 0, color: '#ef4444' },
    { name: '100%', value: report?.compBills.length || 0, color: '#991b1b' },
  ].filter(d => d.value > 0);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200">
      {/* Sidebar / Nav */}
      <header className="sticky top-0 z-50 bg-slate-900/80 backdrop-blur-md border-b border-slate-800 px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <ShieldAlert className="w-8 h-8 text-red-500" />
          <h1 className="text-xl font-bold tracking-tight text-white">Forensic Discount Auditor</h1>
        </div>
        <div className="flex items-center gap-4">
          <label className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg cursor-pointer transition-colors text-sm font-medium">
            <FileUp className="w-4 h-4" />
            Upload Sales Data
            <input type="file" accept=".csv" onChange={handleFileUpload} className="hidden" />
          </label>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-6 space-y-8">
        {!report && !loading && (
          <div className="flex flex-col items-center justify-center py-20 text-center space-y-6">
            <div className="bg-slate-900 p-8 rounded-full border border-slate-800">
              <Search className="w-16 h-16 text-slate-700" />
            </div>
            <div>
              <h2 className="text-2xl font-semibold text-white">Awaiting Data Input</h2>
              <p className="text-slate-400 max-w-md mt-2">
                Upload your retail CSV file with columns: Store, Sales, (-) Discount, Paid Amount, Customer Name, Phone, Remarks, and Employee.
              </p>
            </div>
            <button 
              onClick={() => document.querySelector('input')?.click()}
              className="bg-slate-800 hover:bg-slate-700 px-6 py-3 rounded-xl border border-slate-700 transition-all"
            >
              Get Started
            </button>
          </div>
        )}

        {loading && (
          <div className="flex flex-col items-center justify-center py-20">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500 mb-4"></div>
            <p className="text-blue-400 font-mono">Running Forensic Audit Algorithms...</p>
          </div>
        )}

        {report && (
          <>
            {/* Tabs */}
            <div className="flex border-b border-slate-800 gap-6">
              {[
                { id: 'dashboard', icon: LayoutDashboard, label: 'Dashboard' },
                { id: 'bills', icon: FileText, label: 'Audit Flags' },
                { id: 'loyalty', icon: Users, label: 'Loyalty Integrity' },
                { id: 'stores', icon: Activity, label: 'Store Benchmarking' },
              ].map(tab => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id as any)}
                  className={`flex items-center gap-2 pb-4 transition-all relative ${
                    activeTab === tab.id ? 'text-blue-400' : 'text-slate-500 hover:text-slate-300'
                  }`}
                >
                  <tab.icon className="w-4 h-4" />
                  <span className="font-medium text-sm">{tab.label}</span>
                  {activeTab === tab.id && <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]"></div>}
                </button>
              ))}
            </div>

            {activeTab === 'dashboard' && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-500">
                {/* Stats Row */}
                <div className="lg:col-span-3 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                  <StatsCard 
                    title="Avg System Discount" 
                    value={`${report.overallAvgDiscount.toFixed(2)}%`}
                    color="blue"
                    icon={<TrendingDown className="text-blue-400 w-5 h-5" />}
                  />
                  <StatsCard 
                    title="High Discount Bills" 
                    value={report.highDiscountBills.length}
                    subtitle="> 10% threshold"
                    color="yellow"
                    icon={<AlertCircle className="text-yellow-400 w-5 h-5" />}
                  />
                  <StatsCard 
                    title="Extreme Discounts" 
                    value={report.extremeDiscountBills.length + report.compBills.length}
                    subtitle="75% to 100% loss"
                    color="red"
                    icon={<ShieldAlert className="text-red-400 w-5 h-5" />}
                  />
                  <StatsCard 
                    title="Loyalty Flags" 
                    value={report.suspiciousLoyalty.length}
                    subtitle="Potential Staff Loading"
                    color="green"
                    icon={<Users className="text-green-400 w-5 h-5" />}
                  />
                </div>

                {/* Main Content Area */}
                <div className="lg:col-span-2 space-y-6">
                  {/* AI Summary Card */}
                  <div className="bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden">
                    <div className="bg-slate-800/50 px-6 py-4 border-b border-slate-800 flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <ShieldAlert className="w-5 h-5 text-blue-400" />
                        <h3 className="font-semibold text-white">Forensic Auditor Intelligence</h3>
                      </div>
                      <span className="text-[10px] px-2 py-0.5 bg-blue-500/10 text-blue-400 border border-blue-500/20 rounded-full font-bold uppercase tracking-widest">Live Analysis</span>
                    </div>
                    <div className="p-6">
                      <p className="text-slate-300 leading-relaxed italic border-l-2 border-slate-700 pl-4 mb-6">
                        "{report.aiExecutiveSummary}"
                      </p>
                      <div className="space-y-3">
                        <h4 className="text-xs font-bold text-slate-500 uppercase tracking-widest">Recommended Actions</h4>
                        {report.aiActionList.map((action, i) => (
                          <div key={i} className="flex items-start gap-3 bg-slate-800/30 p-3 rounded-lg border border-slate-700/50">
                            <ArrowRightCircle className="w-4 h-4 text-blue-500 mt-0.5 flex-shrink-0" />
                            <span className="text-sm text-slate-300">{action}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>

                  {/* Chart Card */}
                  <div className="bg-slate-900 rounded-2xl border border-slate-800 p-6">
                    <h3 className="font-semibold text-white mb-6">Top 10 High-Discount Stores</h3>
                    <div className="h-64">
                      <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={chartData}>
                          <CartesianGrid strokeDasharray="3 3" stroke="#334155" />
                          <XAxis dataKey="storeName" stroke="#94a3b8" fontSize={10} />
                          <YAxis stroke="#94a3b8" fontSize={10} label={{ value: 'Avg %', angle: -90, position: 'insideLeft', fill: '#94a3b8' }} />
                          <Tooltip 
                            contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #334155', borderRadius: '8px' }}
                            itemStyle={{ color: '#60a5fa' }}
                          />
                          <Bar dataKey="avgDiscount" fill="#3b82f6" radius={[4, 4, 0, 0]}>
                            {chartData.map((entry, index) => (
                              <Cell key={`cell-${index}`} fill={entry.avgDiscount > report.overallAvgDiscount * 1.5 ? '#f43f5e' : '#3b82f6'} />
                            ))}
                          </Bar>
                        </BarChart>
                      </ResponsiveContainer>
                    </div>
                  </div>
                </div>

                {/* Sidebar area */}
                <div className="space-y-6">
                  <div className="bg-slate-900 rounded-2xl border border-slate-800 p-6">
                    <h3 className="font-semibold text-white mb-6">Discount Distribution</h3>
                    <div className="h-64">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie
                            data={discountDistData}
                            innerRadius={60}
                            outerRadius={80}
                            paddingAngle={5}
                            dataKey="value"
                          >
                            {discountDistData.map((entry, index) => (
                              <Cell key={`cell-${index}`} fill={entry.color} />
                            ))}
                          </Pie>
                          <Tooltip />
                          <Legend verticalAlign="bottom" height={36}/>
                        </PieChart>
                      </ResponsiveContainer>
                    </div>
                    <div className="mt-4 pt-4 border-t border-slate-800 space-y-2">
                      <p className="text-xs text-slate-500">Total Flagged Bills: {report.highDiscountBills.length}</p>
                      <p className="text-xs text-slate-500">Revenue at Risk: ${report.compBills.reduce((s,t) => s+t.sales, 0).toLocaleString()}</p>
                    </div>
                  </div>

                  <div className="bg-red-950/20 rounded-2xl border border-red-500/20 p-6">
                    <div className="flex items-center gap-2 text-red-400 mb-4">
                      <AlertCircle className="w-5 h-5" />
                      <h3 className="font-semibold">Urgent Warnings</h3>
                    </div>
                    <div className="space-y-4">
                      {report.compBills.length > 0 && (
                        <div className="text-sm">
                          <span className="font-bold block text-red-500">{report.compBills.length} Complimentary Bills</span>
                          <span className="text-slate-400">100% discounts detected. Verify manager overrides immediately.</span>
                        </div>
                      )}
                      {report.suspiciousLoyalty.length > 5 && (
                        <div className="text-sm">
                          <span className="font-bold block text-red-500">Loyalty Loophole Detected</span>
                          <span className="text-slate-400">Multiple accounts sharing phone numbers. High risk of staff point loading.</span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'bills' && (
              <div className="bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden animate-in slide-in-from-bottom-5">
                <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-slate-800/30">
                  <h3 className="font-semibold text-white">Flagged Transactions (Discount > 10%)</h3>
                  <button className="text-xs bg-slate-700 hover:bg-slate-600 px-3 py-1.5 rounded-lg border border-slate-600 transition-colors">Export Flagged Bills</button>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left">
                    <thead className="text-xs uppercase bg-slate-800/50 text-slate-400 font-mono">
                      <tr>
                        <th className="px-6 py-4">Bill ID</th>
                        <th className="px-6 py-4">Store</th>
                        <th className="px-6 py-4 text-right">Sales</th>
                        <th className="px-6 py-4 text-right">Disc %</th>
                        <th className="px-6 py-4">Employee</th>
                        <th className="px-6 py-4">Remarks Audit</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800">
                      {report.highDiscountBills.slice(0, 50).map((bill, i) => (
                        <tr key={i} className="hover:bg-slate-800/30 transition-colors">
                          <td className="px-6 py-4 font-medium text-slate-300">{bill.billId}</td>
                          <td className="px-6 py-4">{bill.store}</td>
                          <td className="px-6 py-4 text-right font-mono">${bill.sales.toFixed(2)}</td>
                          <td className={`px-6 py-4 text-right font-bold ${
                            bill.discountPercentage === 100 ? 'text-red-500' : 
                            bill.discountPercentage >= 75 ? 'text-orange-500' : 'text-yellow-500'
                          }`}>
                            {bill.discountPercentage.toFixed(1)}%
                          </td>
                          <td className="px-6 py-4 text-slate-400">{bill.employee}</td>
                          <td className="px-6 py-4">
                            {!bill.remarks || bill.remarks.trim().length < 3 ? (
                              <span className="text-[10px] px-2 py-0.5 bg-red-500/10 text-red-500 border border-red-500/20 rounded font-bold">REMARK MISSING</span>
                            ) : (
                              <span className="text-slate-500 italic truncate max-w-[150px] inline-block">"{bill.remarks}"</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                  {report.highDiscountBills.length > 50 && (
                    <div className="p-4 text-center text-xs text-slate-500 italic bg-slate-800/20">
                      Showing top 50 transactions. Download CSV for full audit trail.
                    </div>
                  )}
                </div>
              </div>
            )}

            {activeTab === 'loyalty' && (
              <div className="space-y-6 animate-in slide-in-from-bottom-5">
                <div className="bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden">
                   <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-slate-800/30">
                    <h3 className="font-semibold text-white">Suspicious Loyalty Activity</h3>
                  </div>
                  <div className="p-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                      {report.suspiciousLoyalty.map((s, i) => (
                        <div key={i} className="bg-slate-800/40 border border-slate-700 rounded-xl p-5 hover:border-red-500/50 transition-all">
                          <div className="flex justify-between items-start mb-4">
                            <span className="text-lg font-bold text-white font-mono">{s.phone}</span>
                            <div className="flex flex-col gap-1 items-end">
                              {s.flags.map((f, idx) => (
