                        <th className="px-6 py-4 text-right">Total Revenue</th>
                        <th className="px-6 py-4 text-right">Flagged Bills</th>
                        <th className="px-6 py-4">Audit Category</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800">
                      {report.storeBenchmarking.map((store, i) => (
                        <tr key={i} className="hover:bg-slate-800/30 transition-colors">
                          <td className="px-6 py-4 font-semibold text-slate-300">{store.storeName}</td>
                          <td className="px-6 py-4 text-right font-mono">{store.avgDiscount.toFixed(2)}%</td>
                          <td className="px-6 py-4 text-right font-mono">${store.totalSales.toLocaleString()}</td>
                          <td className="px-6 py-4 text-right font-bold text-slate-300">{store.suspiciousCount}</td>
                          <td className="px-6 py-4">
                            <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${
                              store.category === 'High' ? 'bg-red-500/10 text-red-500 border border-red-500/20' : 
                              store.category === 'Low' ? 'bg-green-500/10 text-green-500 border border-green-500/20' : 
                              'bg-blue-500/10 text-blue-500 border border-blue-500/20'
                            }`}>
                              {store.category} Risk
                            </span>
