            )}
          </>
        )}
      </main>

      <footer className="mt-20 border-t border-slate-900 py-10 px-6 text-center text-slate-600 text-xs">
        <p>&copy; {new Date().getFullYear()} Forensic Discount Auditor - Professional Data Analytics & Fraud Detection Suite</p>
        <p className="mt-1 font-mono">Powered by Gemini AI reasoning engine</p>
