                    </div>
                    <div className="space-y-4">
                      {report.compBills.length > 0 && <div className="text-sm"><span className="font-bold block text-red-500">{report.compBills.length} Complimentary Bills</span><span className="text-slate-400">100% discounts detected. Verify manager overrides.</span></div>}
