                      onClick={() => exportListToExcel(report.extremeDiscountBills, "Bills_75to90pct_Discount")}
                      className="flex items-center gap-2 text-[10px] bg-orange-600/20 hover:bg-orange-600/30 text-orange-500 px-3 py-1.5 rounded-lg border border-orange-500/30 transition-colors font-bold uppercase"
                    >
                      <Download className="w-3 h-3" />
                      Export 75-90%
                    </button>
