                      onClick={() => exportListToExcel(report.compBills, "Bills_100pct_Discount")}
                      className="flex items-center gap-2 text-[10px] bg-red-600/20 hover:bg-red-600/30 text-red-500 px-3 py-1.5 rounded-lg border border-red-500/30 transition-colors font-bold uppercase"
