                                {(bill.remarks.toLowerCase().includes('staff') || bill.customerName.toLowerCase().includes('staff')) && (
                                  <span className="text-[9px] px-1.5 py-0.5 bg-green-500/10 text-green-500 border border-green-500/20 rounded font-black">STAFF</span>
