              </div>
            )}

            {activeTab === 'loyalty' && (
              <div className="space-y-6 animate-in slide-in-from-bottom-5">
                <div className="bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden shadow-2xl">
                   <div className="p-6 border-b border-slate-800 bg-slate-800/30"><h3 className="font-semibold text-white">Suspicious Loyalty Activity</h3></div>
                  <div className="p-6">
                    {report.suspiciousLoyalty.length > 0 ? (
                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {report.suspiciousLoyalty.map((s, i) => (
                          <div key={i} className="bg-slate-800/40 border border-slate-700 rounded-xl p-5 hover:border-red-500/50 transition-all shadow-lg">
                            <div className="flex justify-between items-start mb-4">
                              <span className="text-lg font-bold text-white font-mono">{s.phone}</span>
                              <div className="flex flex-col gap-1 items-end">
                                {s.flags.map((f, idx) => (
                                  <span key={idx} className="text-[9px] px-1.5 py-0.5 bg-red-500/10 text-red-500 border border-red-500/20 rounded font-black uppercase tracking-tighter">{f}</span>
                                ))}
