                            </div>
                            <div className="space-y-3 text-xs text-slate-400">
                              <div className="flex justify-between"><span>Txs:</span><span className="text-slate-200 font-bold">{s.transactionCount}</span></div>
                              <div className="flex justify-between"><span>Names:</span><span className="truncate max-w-[120px] text-slate-200">{s.names.join(', ')}</span></div>
