                    ) : (
                      <div className="py-20 text-center">
                        <Users className="w-12 h-12 text-slate-800 mx-auto mb-4" />
                        <p className="text-slate-500">No suspicious loyalty patterns (multi-name or high-frequency) found.</p>
                      </div>
                    )}
