import React, { useState, useMemo, useCallback } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  Cell, PieChart, Pie, Legend 
} from 'recharts';
import { 
  ShieldAlert, 
  FileUp, 
  LayoutDashboard, 
  TrendingDown, 
  Users, 
  AlertCircle,
  FileText,
  Activity,
  ArrowRightCircle,
  UploadCloud,
  Download,
  UserCheck,
  MapPin
} from 'lucide-react';
import { Transaction, AuditReport, StoreBenchmarking, SuspiciousLoyalty } from './types';
import { getForensicSummary } from './geminiService';
import { StatsCard } from './components/StatsCard';
import * as XLSX from 'xlsx';

const App: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'bills' | 'loyalty' | 'stores'>('dashboard');
  const [report, setReport] = useState<AuditReport | null>(null);
  const [dragActive, setDragActive] = useState(false);

  const processFile = useCallback((file: File) => {
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];

        const jsonData = XLSX.utils.sheet_to_json(worksheet) as any[];

        const parsed: Transaction[] = jsonData.map((row, idx) => {
          const findVal = (keys: string[]) => {
            const match = Object.keys(row).find(k => {
              const normalizedK = k.toLowerCase().replace(/[^a-z0-9]/g, '');
              return keys.some(key => normalizedK === key.toLowerCase().replace(/[^a-z0-9]/g, ''));
            });
            return match ? row[match] : undefined;
          };

          const sales = parseFloat(findVal(['sales', 'grosssales', 'total', 'billamount', 'grossamount'])) || 0;
          const discount = Math.abs(parseFloat(findVal(['discount', '(-)discount', 'discounts', 'discountamt', 'discamt'])) || 0);
          const paid = parseFloat(findVal(['paidamount', 'netbill', 'finalamount', 'netsales', 'netamount'])) || 0;

          return {
            billId: String(findVal(['billid', 'billno', 'invoice', 'receipt']) || `B-${idx}`),
            store: String(findVal(['store', 'outlet', 'location', 'branch']) || 'Unknown'),
            sales,
            discount,
            paidAmount: paid,
            customerName: String(findVal(['customername', 'name', 'customer', 'custname']) || 'Guest'),
            customerPhone: String(findVal(['phone', 'customerphone', 'mobile', 'contact']) || '0000000000').trim(),
            remarks: String(findVal(['remarks', 'reason', 'comment', 'discreason']) || ''),
            employee: String(findVal(['employee', 'staff', 'cashier', 'user']) || 'N/A'),
            date: String(findVal(['date', 'billdate', 'timestamp', 'datetime']) || new Date().toISOString()),
            discountPercentage: sales > 0 ? (discount / sales) * 100 : 0
          };
        }).filter(t => {
          const remarksLower = t.remarks.toLowerCase();
          const isMrpExcluded = remarksLower.includes('mrp'); 
          const hasReasonableData = t.sales > 0 || t.discount > 0;
          return hasReasonableData && !isMrpExcluded;
        });

        if (parsed.length === 0) {
          alert("No valid data found after filtering. Ensure column headers like 'Sales' and 'Discount' are present.");
          setLoading(false);
          return;
        }

        runAudit(parsed);
      } catch (err) {
        console.error("Error parsing Excel:", err);
        alert("Failed to process Excel file. Please check file format.");
        setLoading(false);
      }
    };
    reader.readAsArrayBuffer(file);
  }, []);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) processFile(file);
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") setDragActive(true);
    else if (e.type === "dragleave") setDragActive(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) processFile(e.dataTransfer.files[0]);
  };

  const runAudit = async (transactions: Transaction[]) => {
    const totalSales = transactions.reduce((sum, t) => sum + t.sales, 0);
    const totalDiscount = transactions.reduce((sum, t) => sum + t.discount, 0);
    const overallAvgDiscount = totalSales > 0 ? (totalDiscount / totalSales) * 100 : 0;

    const highDiscountBills = transactions.filter(t => t.discountPercentage > 10);
    const extremeDiscountBills = transactions.filter(t => t.discountPercentage >= 75 && t.discountPercentage <= 90);
    const compBills = transactions.filter(t => t.discountPercentage === 100);

    const staffDiscountBills = transactions.filter(t => {
      const remarks = t.remarks.toLowerCase();
      const name = t.customerName.toLowerCase();
      return remarks.includes('staff') || name.includes('staff');
    });

    const storeMap = new Map<string, Transaction[]>();
    transactions.forEach(t => {
      const list = storeMap.get(t.store) || [];
      list.push(t);
      storeMap.set(t.store, list);
    });

    const storeBenchmarking: StoreBenchmarking[] = Array.from(storeMap.entries()).map(([storeName, txs]) => {
      const sSales = txs.reduce((sum, t) => sum + t.sales, 0);
      const sDisc = txs.reduce((sum, t) => sum + t.discount, 0);
      const avg = sSales > 0 ? (sDisc / sSales) * 100 : 0;
      let category: 'High' | 'Low' | 'Average' = 'Average';
      if (avg >= overallAvgDiscount * 1.5) category = 'High';
      else if (avg <= overallAvgDiscount * 0.5) category = 'Low';
      return { storeName, avgDiscount: avg, totalSales: sSales, totalDiscount: sDisc, category, suspiciousCount: txs.filter(t => t.discountPercentage > 10).length };
    });

    // LOYALTY AUDIT LOGIC
    const phoneMap = new Map<string, { names: Set<string>; txs: Transaction[] }>();
    transactions.forEach(t => {
      const phone = t.customerPhone;

      // Filter out repeated digit dummy numbers (9999999999, 0000000000, etc) 
      // and common dummy sequences
      const isRepetitive = /^(.)\1+$/.test(phone);
      const isCommonDummy = ['1234567890', '0123456789'].includes(phone);
      const isTooShort = phone.length < 5;

      if (isRepetitive || isCommonDummy || isTooShort) return; 

      const entry = phoneMap.get(phone) || { names: new Set(), txs: [] };
      entry.names.add(t.customerName);
      entry.txs.push(t);
      phoneMap.set(phone, entry);
    });

    const suspiciousLoyalty: SuspiciousLoyalty[] = Array.from(phoneMap.entries())
      .map(([phone, entry]) => {
        const flags: string[] = [];
        const uniqueNames = Array.from(entry.names);
        const stores = Array.from(new Set(entry.txs.map(t => t.store)));

        if (uniqueNames.length > 2) flags.push("Proxy ID (Multi-Name)");
        if (entry.txs.length > 15) flags.push("Excessive Frequency");
        if (stores.length > 3) flags.push("Multi-Store Hopping");

        return { 
          phone, 
          names: uniqueNames, 
          transactionCount: entry.txs.length, 
          stores: stores, 
          employees: Array.from(new Set(entry.txs.map(t => t.employee))), 
          flags 
        };
      })
      .filter(s => s.flags.length > 0)
      .sort((a, b) => b.transactionCount - a.transactionCount);

    const baseReport: AuditReport = {
      overallAvgDiscount, 
      totalTransactions: transactions.length, 
      highDiscountBills, 
      extremeDiscountBills, 
      compBills, 
      staffDiscountBills,
      storeBenchmarking, 
      suspiciousLoyalty, 
      aiExecutiveSummary: "Forensic Analysis in Progress...", 
      aiActionList: []
    };

    setReport(baseReport);
    const aiResponse = await getForensicSummary(baseReport);
    setReport(prev => prev ? { ...prev, aiExecutiveSummary: aiResponse.executiveSummary, aiActionList: aiResponse.actionList } : null);
    setLoading(false);
  };

  const exportListToExcel = (list: Transaction[], filename: string) => {
    if (!list || list.length === 0) {
      alert("No data available for this report.");
      return;
    }
    const worksheet = XLSX.utils.json_to_sheet(list);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Audit Data");
    XLSX.writeFile(workbook, `${filename}.xlsx`);
  };

  const chartData = useMemo(() => {
    if (!report) return [];
    return report.storeBenchmarking.sort((a, b) => b.avgDiscount - a.avgDiscount).slice(0, 10);
  }, [report]);

  const discountDistData = [
    { name: '>10%', value: report?.highDiscountBills.length || 0, color: '#f59e0b' },
    { name: '75-90%', value: report?.extremeDiscountBills.length || 0, color: '#ef4444' },
