            )}

            {activeTab === 'loyalty' && (
              <div className="space-y-6 animate-in slide-in-from-bottom-5">
                <div className="bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden shadow-2xl">
                   <div className="p-6 border-b border-slate-800 bg-slate-800/30 flex justify-between items-center">
                    <h3 className="font-semibold text-white">Suspicious Loyalty Integrity Audit</h3>
                    <div className="flex gap-2">
                      <span className="text-[10px] bg-red-500/10 text-red-400 px-2 py-1 rounded border border-red-500/20 font-mono">Filter: &gt;10 Bills</span>
                      <span className="text-[10px] bg-blue-500/10 text-blue-400 px-2 py-1 rounded border border-blue-500/20 font-mono">Dummy Sanitization Active</span>
                    </div>
                  </div>
                  <div className="p-6">
                    {report.suspiciousLoyalty.length > 0 ? (
                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {report.suspiciousLoyalty.map((s, i) => (
                          <div key={i} className="bg-slate-800/40 border border-slate-700 rounded-xl p-5 hover:border-blue-500/50 transition-all shadow-lg flex flex-col h-full group">
                            <div className="flex justify-between items-start mb-4">
                              <div className="flex flex-col">
                                <span className="text-xl font-bold text-white font-mono group-hover:text-blue-400 transition-colors">{s.phone}</span>
                                <span className="text-[10px] text-slate-500 uppercase font-bold tracking-widest mt-1">Identity Profile</span>
