                            <div className="space-y-4 flex-grow">
                              <div className="grid grid-cols-2 gap-2">
                                <div className="bg-green-500/5 border border-green-500/20 rounded-lg p-3">
                                  <div className="flex items-center gap-1.5 text-green-500 mb-1">
                                    <ArrowUpRight className="w-3 h-3" />
                                    <span className="text-[9px] font-bold uppercase">Points Gained</span>
                                  </div>
                                  <div className="text-lg font-bold text-green-400 font-mono">{s.totalPointsGained.toLocaleString()}</div>
                                </div>
                                <div className="bg-orange-500/5 border border-orange-500/20 rounded-lg p-3">
                                  <div className="flex items-center gap-1.5 text-orange-500 mb-1">
                                    <ArrowDownRight className="w-3 h-3" />
                                    <span className="text-[9px] font-bold uppercase">Redeemed</span>
                                  </div>
                                  <div className="text-lg font-bold text-orange-400 font-mono">{s.totalPointsRedeemed.toLocaleString()}</div>
                                </div>
