                              <div className="bg-slate-900/50 p-3 rounded-lg border border-slate-700/50">
                                <div className="flex items-center gap-2 mb-2">
                                  <MapPin className="w-3 h-3 text-blue-400" />
                                  <span className="text-[10px] font-bold text-slate-400 uppercase">Stores Detected</span>
                                </div>
                                <div className="flex flex-wrap gap-1.5">
                                  {s.stores.map((store, idx) => (
                                    <span key={idx} className="px-2 py-0.5 bg-blue-500/10 text-blue-400 border border-blue-500/20 rounded text-[10px] font-medium">
                                      {store}
                                    </span>
                                  ))}
                                </div>
                              </div>

                              <div className="grid grid-cols-2 gap-2">
                                <div className="bg-slate-900/50 p-2 rounded border border-slate-700/50 text-center">
                                  <div className="text-[9px] text-slate-500 uppercase font-bold mb-1">Total Bills</div>
                                  <div className="text-lg font-bold text-white font-mono">{s.transactionCount}</div>
                                </div>
                                <div className="bg-slate-900/50 p-2 rounded border border-slate-700/50 text-center">
                                  <div className="text-[9px] text-slate-500 uppercase font-bold mb-1">Unq. Names</div>
                                  <div className="text-lg font-bold text-white font-mono">{s.names.length}</div>
                                </div>
                              </div>

                              <div>
                                <div className="text-[10px] text-slate-500 uppercase font-bold mb-2">Registration Names:</div>
                                <div className="flex flex-wrap gap-1">
                                  {s.names.map((n, idx) => (
                                    <span key={idx} className="px-2 py-0.5 bg-slate-700 text-slate-300 rounded text-[9px] border border-slate-600">
                                      {n}
                                    </span>
                                  ))}
                                </div>
                              </div>
                            </div>

                            <div className="mt-4 pt-4 border-t border-slate-700/50 flex justify-between items-center">
                              <span className="text-[9px] text-slate-500 italic">Audit Action: Manual Review</span>
                              <div className="flex -space-x-1">
                                {s.employees.slice(0, 3).map((e, idx) => (
                                  <div key={idx} className="w-5 h-5 rounded-full bg-slate-700 border border-slate-900 flex items-center justify-center text-[8px] font-bold text-slate-400 uppercase" title={e}>
                                    {e.charAt(0)}
                                  </div>
                                ))}
                                {s.employees.length > 3 && (
                                  <div className="w-5 h-5 rounded-full bg-slate-800 border border-slate-900 flex items-center justify-center text-[8px] font-bold text-slate-400">
                                    +{s.employees.length - 3}
                                  </div>
                                )}
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="py-20 text-center">
                        <Users className="w-12 h-12 text-slate-800 mx-auto mb-4" />
                        <p className="text-slate-500">No phone numbers with more than 10 bills detected.</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'stores' && (
              <div className="bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden animate-in slide-in-from-bottom-5 shadow-2xl">
                <div className="p-6 border-b border-slate-800 bg-slate-800/30"><h3 className="font-semibold text-white">Store Performance Benchmarking</h3></div>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left">
                    <thead className="text-xs uppercase bg-slate-800/50 text-slate-400 font-mono">
                      <tr>
                        <th className="px-6 py-4">Store</th>
                        <th className="px-6 py-4 text-right">Avg Disc %</th>
                        <th className="px-6 py-4 text-right">Total Revenue</th>
                        <th className="px-6 py-4">Audit Result</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800">
                      {report.storeBenchmarking.map((store, i) => (
                        <tr key={i} className="hover:bg-slate-800/30 transition-colors">
                          <td className="px-6 py-4 font-semibold text-slate-300">{store.storeName}</td>
                          <td className="px-6 py-4 text-right font-mono">{store.avgDiscount.toFixed(2)}%</td>
                          <td className="px-6 py-4 text-right font-mono">₹{store.totalSales.toLocaleString('en-IN')}</td>
                          <td className="px-6 py-4">
                            <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${store.category === 'High' ? 'bg-red-500/10 text-red-500 border border-red-500/20' : store.category === 'Low' ? 'bg-green-500/10 text-green-500 border border-green-500/20' : 'bg-blue-500/10 text-blue-500 border border-blue-500/20'}`}>
                              {store.category} Risk
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </>
        )}
      </main>

      <footer className="mt-20 border-t border-slate-900 py-10 px-6 text-center text-slate-600 text-xs font-mono">
        <p>Forensic Discount Auditor • Version 2.6 • Threshold: &gt;10 Bills • Functioning Reset</p>
      </footer>
    </div>
  );
};

export default App;

export interface Transaction {
  billId: string;
  store: string;
  sales: number;
  discount: number;
  paidAmount: number;
  customerName: string;
  customerPhone: string;
  remarks: string;
  employee: string;
  date: string;
  discountPercentage: number;
  pointsGained: number;
  pointsRedeemed: number;
}

export interface StoreBenchmarking {
  storeName: string;
  avgDiscount: number;
  totalSales: number;
  totalDiscount: number;
  category: 'High' | 'Low' | 'Average';
  suspiciousCount: number;
}

export interface SuspiciousLoyalty {
  phone: string;
  names: string[];
  transactionCount: number;
  stores: string[];
  employees: string[];
  flags: string[];
  totalPointsGained: number;
  totalPointsRedeemed: number;
}

export interface AuditReport {
  overallAvgDiscount: number;
  totalTransactions: number;
  highDiscountBills: Transaction[]; // > 10%
  extremeDiscountBills: Transaction[]; // 75-90%
  compBills: Transaction[]; // 100%
  staffDiscountBills: Transaction[]; // Remarks/Name contains "Staff"
  storeBenchmarking: StoreBenchmarking[];
  suspiciousLoyalty: SuspiciousLoyalty[];
  loyaltyThreshold: number;
  aiExecutiveSummary: string;
  aiActionList: string[];
}

import React, { useState, useMemo, useCallback } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  Cell, PieChart, Pie, Legend 
} from 'recharts';
import { 
  ShieldAlert, 
  FileUp, 
  LayoutDashboard, 
  TrendingDown, 
  Users, 
  AlertCircle,
  FileText,
  Activity,
  ArrowRightCircle,
  UploadCloud,
  Download,
  UserCheck,
  MapPin,
  ArrowUpRight,
  ArrowDownRight,
  RotateCcw,
  Calendar
} from 'lucide-react';
import { Transaction, AuditReport, StoreBenchmarking, SuspiciousLoyalty } from './types';
import { getForensicSummary } from './geminiService';
import { StatsCard } from './components/StatsCard';
import * as XLSX from 'xlsx';

const App: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'bills' | 'loyalty' | 'stores'>('dashboard');
  const [report, setReport] = useState<AuditReport | null>(null);
  const [dragActive, setDragActive] = useState(false);

  const resetData = useCallback(() => {
    setReport(null);
    setLoading(false);
    setActiveTab('dashboard');
  }, []);

  const processFile = useCallback((file: File) => {
    setLoading(true);
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];

        const jsonData = XLSX.utils.sheet_to_json(worksheet) as any[];

        const parsed: Transaction[] = jsonData.map((row, idx) => {
          const findVal = (keys: string[]) => {
            const match = Object.keys(row).find(k => {
              const normalizedK = k.toLowerCase().replace(/[^a-z0-9]/g, '');
              return keys.some(key => normalizedK === key.toLowerCase().replace(/[^a-z0-9]/g, ''));
            });
            return match ? row[match] : undefined;
          };

          const sales = parseFloat(findVal(['sales', 'grosssales', 'total', 'billamount', 'grossamount'])) || 0;
          const discount = Math.abs(parseFloat(findVal(['discount', '(-)discount', 'discounts', 'discountamt', 'discamt'])) || 0);
          const paid = parseFloat(findVal(['paidamount', 'netbill', 'finalamount', 'netsales', 'netamount'])) || 0;

          const pointsGained = parseFloat(findVal(['loyaltypointsearned', 'pointsgained', 'earned', 'pts+', 'loyaltyearned', 'pointsadded'])) || 0;
          const pointsRedeemed = Math.abs(parseFloat(findVal(['loyaltypointsredeemed', 'pointsredeemed', 'used', 'pts-', 'redeemed', 'pointsburnt']))) || 0;

          return {
            billId: String(findVal(['billid', 'billno', 'invoice', 'receipt']) || `B-${idx}`),
            store: String(findVal(['store', 'outlet', 'location', 'branch']) || 'Unknown'),
            sales,
            discount,
            paidAmount: paid,
            customerName: String(findVal(['customername', 'name', 'customer', 'custname']) || 'Guest'),
            customerPhone: String(findVal(['phone', 'customerphone', 'mobile', 'contact']) || '0000000000').trim(),
            remarks: String(findVal(['remarks', 'reason', 'comment', 'discreason']) || ''),
            employee: String(findVal(['employee', 'staff', 'cashier', 'user']) || 'N/A'),
            date: String(findVal(['date', 'billdate', 'timestamp', 'datetime']) || new Date().toISOString()),
            discountPercentage: sales > 0 ? (discount / sales) * 100 : 0,
            pointsGained,
            pointsRedeemed
          };
        }).filter(t => {
          const remarksLower = t.remarks.toLowerCase();
          const isMrpExcluded = remarksLower.includes('mrp'); 
          const hasReasonableData = t.sales > 0 || t.discount > 0 || t.pointsGained > 0 || t.pointsRedeemed > 0;
          return hasReasonableData && !isMrpExcluded;
        });

        if (parsed.length === 0) {
          alert("No valid data found after filtering. Ensure column headers are present.");
          setLoading(false);
          return;
        }

        runAudit(parsed);
      } catch (err) {
        console.error("Error parsing Excel:", err);
        alert("Failed to process Excel file.");
        setLoading(false);
      }
    };
    reader.readAsArrayBuffer(file);
  }, []);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      processFile(file);
      event.target.value = ''; // Ensure same file can be uploaded after reset
    }
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") setDragActive(true);
    else if (e.type === "dragleave") setDragActive(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) processFile(e.dataTransfer.files[0]);
  };

  const runAudit = async (transactions: Transaction[]) => {
    const totalSales = transactions.reduce((sum, t) => sum + t.sales, 0);
    const totalDiscount = transactions.reduce((sum, t) => sum + t.discount, 0);
    const overallAvgDiscount = totalSales > 0 ? (totalDiscount / totalSales) * 100 : 0;

    const highDiscountBills = transactions.filter(t => t.discountPercentage > 10);
    const extremeDiscountBills = transactions.filter(t => t.discountPercentage >= 75 && t.discountPercentage <= 90);
    const compBills = transactions.filter(t => t.discountPercentage === 100);

    const staffDiscountBills = transactions.filter(t => {
      const remarks = t.remarks.toLowerCase();
      const name = t.customerName.toLowerCase();
      return remarks.includes('staff') || name.includes('staff');
    });

    // Determine unique days to set dynamic threshold
    const uniqueDates = new Set(transactions.map(t => {
      const d = new Date(t.date);
      return isNaN(d.getTime()) ? t.date.split(' ')[0] : d.toISOString().split('T')[0];
    }));
    const loyaltyThreshold = uniqueDates.size > 1 ? 10 : 3;

    const storeMap = new Map<string, Transaction[]>();
    transactions.forEach(t => {
      const list = storeMap.get(t.store) || [];
      list.push(t);
      storeMap.set(t.store, list);
    });

    const storeBenchmarking: StoreBenchmarking[] = Array.from(storeMap.entries()).map(([storeName, txs]) => {
      const sSales = txs.reduce((sum, t) => sum + t.sales, 0);
      const sDisc = txs.reduce((sum, t) => sum + t.discount, 0);
      const avg = sSales > 0 ? (sDisc / sSales) * 100 : 0;
      let category: 'High' | 'Low' | 'Average' = 'Average';
      if (avg >= overallAvgDiscount * 1.5) category = 'High';
      else if (avg <= overallAvgDiscount * 0.5) category = 'Low';
      return { storeName, avgDiscount: avg, totalSales: sSales, totalDiscount: sDisc, category, suspiciousCount: txs.filter(t => t.discountPercentage > 10).length };
    });

    // LOYALTY AUDIT LOGIC
    const phoneMap = new Map<string, { names: Set<string>; txs: Transaction[] }>();
    transactions.forEach(t => {
      const phone = t.customerPhone;
      const isRepetitive = /^(.)\1+$/.test(phone);
      const isCommonDummy = ['1234567890', '0123456789'].includes(phone);
      const isTooShort = phone.length < 5;
      if (isRepetitive || isCommonDummy || isTooShort) return; 

      const entry = phoneMap.get(phone) || { names: new Set(), txs: [] };
      entry.names.add(t.customerName);
      entry.txs.push(t);
      phoneMap.set(phone, entry);
    });

    const suspiciousLoyalty: SuspiciousLoyalty[] = Array.from(phoneMap.entries())
      .filter(([phone, entry]) => entry.txs.length >= loyaltyThreshold)
      .map(([phone, entry]) => {
        const flags: string[] = [];
        const uniqueNames = Array.from(entry.names);
        const stores = Array.from(new Set(entry.txs.map(t => t.store)));
        const totalPointsGained = entry.txs.reduce((sum, t) => sum + t.pointsGained, 0);
        const totalPointsRedeemed = entry.txs.reduce((sum, t) => sum + t.pointsRedeemed, 0);

        if (uniqueNames.length > 2) flags.push("Proxy ID (Multi-Name)");
        if (entry.txs.length > 20) flags.push("Critical Frequency");
        if (stores.length > 3) flags.push("Multi-Store Activity");
        if (totalPointsRedeemed > 0) flags.push("Points Cashed Out");

        return { 
          phone, names: uniqueNames, transactionCount: entry.txs.length, 
          stores: stores, employees: Array.from(new Set(entry.txs.map(t => t.employee))), 
          flags, totalPointsGained, totalPointsRedeemed
        };
      })
      .sort((a, b) => b.transactionCount - a.transactionCount);

    const baseReport: AuditReport = {
      overallAvgDiscount, totalTransactions: transactions.length, 
      highDiscountBills, extremeDiscountBills, compBills, staffDiscountBills,
      storeBenchmarking, suspiciousLoyalty, loyaltyThreshold,
      aiExecutiveSummary: "Forensic Analysis in Progress...", aiActionList: []
    };

    setReport(baseReport);
    const aiResponse = await getForensicSummary(baseReport);
    setReport(prev => prev ? { ...prev, aiExecutiveSummary: aiResponse.executiveSummary, aiActionList: aiResponse.actionList } : null);
    setLoading(false);
  };

  const exportListToExcel = (list: Transaction[], filename: string) => {
    if (!list || list.length === 0) return alert("No data available.");
    const worksheet = XLSX.utils.json_to_sheet(list);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Audit Data");
    XLSX.writeFile(workbook, `${filename}.xlsx`);
  };

  const chartData = useMemo(() => {
    if (!report) return [];
    return report.storeBenchmarking.sort((a, b) => b.avgDiscount - a.avgDiscount).slice(0, 10);
  }, [report]);

  const discountDistData = [
    { name: '>10%', value: report?.highDiscountBills.length || 0, color: '#f59e0b' },
    { name: '75-90%', value: report?.extremeDiscountBills.length || 0, color: '#ef4444' },
    { name: '100%', value: report?.compBills.length || 0, color: '#991b1b' },
  ].filter(d => d.value > 0);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200">
      <header className="sticky top-0 z-50 bg-slate-900/80 backdrop-blur-md border-b border-slate-800 px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <ShieldAlert className="w-8 h-8 text-red-500" />
          <h1 className="text-xl font-bold tracking-tight text-white">Forensic Discount Auditor</h1>
        </div>
        <div className="flex items-center gap-3">
          <label className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg cursor-pointer transition-colors text-sm font-medium shadow-lg shadow-blue-900/20">
            <FileUp className="w-4 h-4" />
            Upload Excel
            <input type="file" accept=".xlsx, .xls" onChange={handleFileUpload} className="hidden" />
          </label>
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-6 space-y-8">
        {!report && !loading && (
          <div 
            className={`flex flex-col items-center justify-center py-20 text-center space-y-6 border-2 border-dashed rounded-3xl transition-all duration-300 ${
              dragActive ? 'border-blue-500 bg-blue-500/5 scale-[1.02]' : 'border-slate-800 bg-slate-900/20'
            }`}
            onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}
          >
            <div className={`p-8 rounded-full border transition-all duration-300 ${dragActive ? 'bg-blue-600/20 border-blue-500' : 'bg-slate-900 border-slate-800'}`}>
              <UploadCloud className={`w-16 h-16 ${dragActive ? 'text-blue-400' : 'text-slate-700'}`} />
            </div>
            <div>
              <h2 className="text-2xl font-semibold text-white">{dragActive ? 'Drop your Excel file here' : 'Drop Excel Data or Click to Upload'}</h2>
              <p className="text-slate-400 max-w-md mt-2 mx-auto">Analyze Sales, Discounts, Customer info, and Remarks for forensic auditing.</p>
            </div>
            <button onClick={() => (document.querySelector('input[type="file"]') as HTMLInputElement)?.click()} className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-xl shadow-lg transition-all font-semibold">Select Excel File</button>
          </div>
        )}

        {loading && (
