                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
          </>
        )}
      </main>

      <footer className="mt-20 border-t border-slate-900 py-10 px-6 text-center text-slate-600 text-xs font-mono uppercase tracking-[0.2em]">
        <p>Forensic Discount Auditor • v2.7.1 • Threshold: {report?.loyaltyThreshold || 10} Bills • Functioning Exports</p>
      </footer>
    </div>
  );
};

