      XLSX.writeFile(workbook, `${safeName}_${new Date().toISOString().split('T')[0]}.xlsx`);
    } catch (err) {
      console.error("Excel Export Error:", err);
      alert("Failed to generate file. Check browser download settings.");
    }
  };

