                            <Info className="w-5 h-5" />
                            Displaying top 60 flagged accounts for performance. Use the global export to view all {report.suspiciousLoyalty.length} accounts.
                          </div>
                        )}
                      </>
                    ) : (
                      <div className="py-48 text-center text-slate-600 font-mono italic text-sm">
                        Zero suspicious loyalty accounts identified using current {report.loyaltyThreshold}-bill benchmark (based on order log time range).
                      </div>
                    )}
