                </div>
              </div>
            )}

            {activeTab === 'stores' && (
              <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden shadow-2xl">
                <div className="p-8 border-b border-slate-800 bg-slate-800/30 flex justify-between items-center">
