                      {report.excessiveLoyaltyBills.length > 0 && <div className="p-4 bg-indigo-500/10 rounded-xl border border-indigo-500/20 text-xs font-bold"><span className="text-indigo-500 text-lg mr-2">{report.excessiveLoyaltyBills.length}</span> Loyalty Burn (>=20%) Bills</div>}
                      {report.compBills.length > 0 && <div className="p-4 bg-red-500/10 rounded-xl border border-red-500/20 text-xs font-bold"><span className="text-red-500 text-lg mr-2">{report.compBills.length}</span> Critical (>=90%) Discounts</div>}
